function oreChance(id,floor){const rule=ORE_RULES.find(r=>r.id===id);if(!rule||floor<1)return 0;const f=Math.min(100,Math.max(1,floor)),[start,middle,end]=rule.chances;return f<=50?start+(middle-start)*(f-1)/49:middle+(end-middle)*(f-50)/50;}
const depositWeightCache=new Map();
function depositWeights(floor){if(floor<1)return [['earth',100]];floor=Math.min(100,Math.max(1,floor));if(depositWeightCache.has(floor))return depositWeightCache.get(floor);const ores=ORE_RULES.map(r=>[r.id,oreChance(r.id,floor)]),total=ores.reduce((sum,[,weight])=>sum+weight,0);const weights=[...ores,['stone',25],['earth',75-total]];depositWeightCache.set(floor,weights);return weights;}
function validMaterialSeed(seed){return Number.isInteger(seed)&&seed>=0&&seed<=0xffffffff;}
function createMaterialSeed(){return Math.floor(Math.random()*0x100000000)>>>0;}
function depositRoll(seed,floor,x,y){let n=(seed^Math.imul(x+1,73856093)^Math.imul(y+1,19349663)^Math.imul(floor,83492791))>>>0;n=Math.imul(n^(n>>>16),0x7feb352d);n=Math.imul(n^(n>>>15),0x846ca68b);return ((n^(n>>>16))>>>0)/0x100000000*100;}
