// Preserve a partly drilled block when upgrading from the short-lived all-ores preview.
function legacyDepositMaterial(seed,floor,x,y){return weightedMaterial(depositRoll(seed,floor,x,y),[['earth',50],['stone',25],['iron',5],['copper',4],['bauxite',3],['tin',2],['zinc',2],['nickel',2],['chromium',2],['titanium',2],['tungsten',1],['gold',1.5],['xenorite',.5]]);}
function restoreMaterialOverrides(value){return new Map(Array.isArray(value)?value.filter(v=>Array.isArray(v)&&Number.isInteger(v[0])&&v[0]>=0&&v[0]<2500&&MATERIALS.some(m=>m.id===v[1])):[]);}


const CARGO_CAPACITY=200;
// Earth/stone are canonical. Ore prices are temporary balance for the new sale UI.
const MATERIAL_PRICES={earth:2,stone:5,iron:12,copper:16,bauxite:20,tin:24,zinc:32,nickel:48,chromium:64,titanium:96,tungsten:160,gold:200,xenorite:1000};
function cargoCount(hold){return MATERIALS.reduce((n,m)=>n+(hold?.[m.id]||0),0);}
function restoreCargo(hold,legacyCount=0,capacity=CARGO_CAPACITY){
 const out={};let remaining=capacity;
 if(hold&&typeof hold==='object'&&!Array.isArray(hold)){
  for(const {id} of MATERIALS){const value=hold[id];if(Number.isSafeInteger(value)&&value>0){out[id]=Math.min(value,remaining);remaining-=out[id];}}
 }else if(Number.isInteger(legacyCount)&&legacyCount>0)out.earth=Math.min(capacity,legacyCount);
 return out;
}
function addCargo(hold,id,capacity=CARGO_CAPACITY){
 if(!Object.hasOwn(MATERIAL_PRICES,id)||cargoCount(hold)>=capacity)return false;
 hold[id]=(hold[id]||0)+1;return true;
}
function quoteCargo(hold,selection,saleBonus=0){
 const sale={};let amount=0,payout=0;
 for(const {id} of MATERIALS){
  const requested=selection?.[id];
  if(!Number.isSafeInteger(requested)||requested<=0)continue;
  const quantity=Math.min(requested,hold[id]||0);
  if(quantity<=0)continue;
  sale[id]=quantity;amount+=quantity;payout+=quantity*MATERIAL_PRICES[id];
 }
 return {sale,amount,payout:Math.round(payout*(1+saleBonus))};
}
function takeCargoSale(hold,selection,saleBonus=0){
 const result=quoteCargo(hold,selection,saleBonus);if(!result.amount)return null;
 for(const [id,count] of Object.entries(result.sale)){hold[id]-=count;if(hold[id]===0)delete hold[id];}
 return {...result,...(saleBonus?{saleBonus}:{}),remaining:10000};
}






const cargoMethods={
 openPorodnik(){
  if(this.porodnikJob||!this.world.porodnikPowered||!onPorodnikDeck(this.rig,this.buildingDeck('porodnik'))||!this.cargo)return;
  this.dialogClosed();this.persist();
  const panel=document.createElement('div');panel.className='cargo-console';
  const intro=document.createElement('p');intro.textContent='Выбери породу и количество для продажи. Остальное останется в буре.';
  const list=document.createElement('div');list.className='cargo-list';
  const rows=[],selection=()=>Object.fromEntries(rows.filter(r=>r.check.checked).map(r=>[r.id,Math.max(0,Math.min(r.count,Math.floor(Number(r.input.value))))]));
  const total=document.createElement('p');total.className='cargo-total';
  const sell=document.createElement('button');sell.className='metal-button';sell.textContent='ПРОДАТЬ ВЫБРАННОЕ · ПЕРЕРАБОТКА 10 С';
  const render=()=>{const quote=quoteCargo(this.cargoHold,selection(),this.collectionBuffs?.sale||0);total.textContent='Продать: '+quote.amount+' · Выручка: '+quote.payout+' кредитов · Оставить: '+(this.cargo-quote.amount);sell.disabled=!quote.amount;};
  for(const m of MATERIALS){
   const count=this.cargoHold[m.id]||0;if(!count)continue;
   const row=document.createElement('div');row.className='cargo-row';
   const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.checked=m.id==='earth';
   const swatch=document.createElement('span');swatch.className='cargo-swatch';const slot=m.frames[0];swatch.style.backgroundPosition=((slot%4)*100/3)+'% '+(Math.floor(slot/4)*100/3)+'%';
   const caption=document.createElement('span'),name=document.createElement('strong'),details=document.createElement('small');
   name.textContent=m.name;details.textContent='В буре: '+count+' · '+MATERIAL_PRICES[m.id]+' кр./шт.';caption.append(name,details);label.append(check,swatch,caption);
   const input=document.createElement('input');input.type='number';input.min='1';input.max=String(count);input.step='1';input.value=String(count);input.disabled=!check.checked;input.setAttribute('aria-label','Количество: '+m.name);
   const stepper=document.createElement('div');stepper.className='cargo-stepper';
   const minus=document.createElement('button'),plus=document.createElement('button');minus.type=plus.type='button';minus.textContent='−';plus.textContent='+';minus.setAttribute('aria-label','Уменьшить: '+m.name);plus.setAttribute('aria-label','Увеличить: '+m.name);
   const enabled=()=>{input.disabled=minus.disabled=plus.disabled=!check.checked;};enabled();
   const step=delta=>{input.value=String(Math.max(1,Math.min(count,(Number(input.value)||1)+delta)));render();};
   minus.addEventListener('click',()=>step(-1));plus.addEventListener('click',()=>step(1));
   check.addEventListener('change',()=>{enabled();render();});input.addEventListener('input',render);stepper.append(minus,input,plus);
   rows.push({id:m.id,count,check,input});row.append(label,stepper);list.append(row);
  }
  sell.addEventListener('click',()=>{if(!this.sellCargo(selection()))return;document.querySelector('#dialog').close();this.dialogClosed();});
  panel.append(intro,list,total,sell);render();
  showBuildingMenu('porodnik',panel);
 },
 sellCargo(selection){
  if(this.porodnikJob||!this.world.porodnikPowered||!onPorodnikDeck(this.rig,this.buildingDeck('porodnik')))return false;
  const job=takeCargoSale(this.cargoHold,selection,this.collectionBuffs?.sale||0);if(!job)return false;
  this.porodnikJob=job;this.cargo=cargoCount(this.cargoHold);this.speed=0;this.refreshHUD();this.persist();return true;
 }
};





function terrainTileIndex(world,x,y) {
  const soil=(cx,cy)=>world.inside(cx,cy)&&world.blocked(cx,cy);
  const filled=soil(x,y);
  const neighbors=[soil(x,y-1),soil(x+1,y),soil(x,y+1),soil(x-1,y)];
  const mask=neighbors.reduce((bits,value,i)=>bits|((filled?!value:value)?1<<i:0),0);
  return filled?((y%4)*4+x%4)*16+mask:256+mask;
}
function soilCornerBounds(mask) {
  return {left:mask&8?11:0,right:mask&2?48:64,top:mask&1?8:0,bottom:mask&4?37:64};
}
function soilFacePolygon(mask,side) {
  if(!(mask&(1<<side)))return [];
  const {left,right,top,bottom}=soilCornerBounds(mask);
  const inner=[[[left,top],[right,top]],[[right,top],[right,bottom]],[[right,bottom],[left,bottom]],[[left,bottom],[left,top]]][side];
  const outer=[[[0,0],[64,0]],[[64,0],[64,64]],[[64,64],[0,64]],[[0,64],[0,0]]][side];
  return [inner[0],inner[1],outer[1],outer[0]];
}
// NW, NE, SE, SW: diagonals expose inside bends hidden by cardinal masks.
function terrainCornerTypes(world,x,y) {
  if(!world.inside(x,y)||!world.blocked(x,y))return [-1,-1,-1,-1];
  const soil=(cx,cy)=>world.inside(cx,cy)&&world.blocked(cx,cy);
  return [[-1,-1],[1,-1],[1,1],[-1,1]].map(([dx,dy],corner)=>{
    const horizontal=soil(x+dx,y),vertical=soil(x,y+dy);
    if(!horizontal&&!vertical)return corner+4;
    if(horizontal&&vertical&&!soil(x+dx,y+dy))return corner;
    return -1;
  });
}
function cornerPatch(ctx,type,variant,face) {
  const corner=type%4,right=corner===1||corner===2,bottom=corner>=2;
  const width=right?16:11,height=bottom?27:8;
  ctx.save();ctx.translate(right?64:0,bottom?64:0);ctx.scale(right?-1:1,bottom?-1:1);
  ctx.beginPath();
  if(type<4) {
    // A concave ellipse joins the two neighboring cut faces at their exact insets.
    ctx.moveTo(0,0);ctx.lineTo(width,0);
    ctx.bezierCurveTo(width,height*.552,width*.552,height,0,height);ctx.closePath();
  } else {
    // Shave the pointed top corner into a small rounded clay rim.
    const r=5;ctx.moveTo(width,height);ctx.lineTo(width+r,height);
    ctx.quadraticCurveTo(width,height,width,height+r);ctx.closePath();
  }
  ctx.save();ctx.clip();
  const panel=variant%4;
  ctx.drawImage(face,panel*face.width/4,0,face.width/4,face.height,0,0,64,height+6);
  const shade=ctx.createLinearGradient(0,0,0,height+5);
  shade.addColorStop(0,'rgba(25,19,14,.48)');shade.addColorStop(1,'rgba(39,23,13,.05)');
  ctx.fillStyle=shade;ctx.fillRect(0,0,64,height+6);ctx.restore();
  ctx.beginPath();
  if(type<4){ctx.moveTo(width,0);ctx.bezierCurveTo(width,height*.552,width*.552,height,0,height);}
  else {ctx.moveTo(width+5,height);ctx.quadraticCurveTo(width,height,width,height+5);}
  ctx.strokeStyle='rgba(248,193,107,.9)';ctx.lineWidth=2.5;ctx.lineCap='round';ctx.stroke();ctx.restore();
}
function cutEdge(ctx,side,variant,face,mask) {
  const polygon=soilFacePolygon(mask,side);
  const inner=polygon.slice(0,2),outer=[polygon[3],polygon[2]];
  const [start,end]=inner,points=[start];
  for(let i=1;i<8;i++) {
    const t=i/8,jitter=(((i+variant*5)%4)-1.5)*.8;
    points.push([start[0]+(end[0]-start[0])*t+(side%2?jitter:0),start[1]+(end[1]-start[1])*t+(side%2?0:jitter)]);
  }
  points.push(end);
  ctx.save();ctx.beginPath();ctx.moveTo(...points[0]);for(const point of points.slice(1))ctx.lineTo(...point);
  ctx.lineTo(...outer[1]);ctx.lineTo(...outer[0]);ctx.closePath();ctx.clip();
  ctx.save();
  if(side===0){ctx.translate(64,64);ctx.rotate(Math.PI);}
  if(side===1){ctx.translate(0,64);ctx.rotate(-Math.PI/2);}
  if(side===3){ctx.translate(64,0);ctx.rotate(Math.PI/2);}
  const depth=side===2?27:side===1?16:side===3?11:8,rim=64-depth;
  const panel=side===1||side===3?Math.floor(variant/4):variant%4;
  ctx.drawImage(face,panel*face.width/4,0,face.width/4,face.height,0,rim-3,64,depth+3);
  const shade=ctx.createLinearGradient(0,rim,0,64);
  shade.addColorStop(0,'rgba(39,23,13,.05)');shade.addColorStop(.55,'rgba(39,23,13,.12)');shade.addColorStop(1,'rgba(25,19,14,.48)');
  ctx.fillStyle=shade;ctx.fillRect(0,rim-3,64,depth+3);
  if(side===1){ctx.fillStyle='rgba(32,23,16,.16)';ctx.fillRect(0,rim-3,64,depth+3);}
  ctx.restore();ctx.restore();
  ctx.beginPath();ctx.moveTo(...points[0]);for(const point of points.slice(1))ctx.lineTo(...point);
  ctx.strokeStyle=side===0||side===3?'rgba(255,211,123,.85)':'rgba(248,186,94,.85)';ctx.lineWidth=2.5;ctx.stroke();
  ctx.strokeStyle='rgba(31,23,17,.7)';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(...outer[0]);ctx.lineTo(...outer[1]);ctx.stroke();
}
function floorShadow(ctx,mask) {
  for(let side=0;side<4;side++) if(mask&(1<<side)) {
    ctx.save();
    if(side===1){ctx.translate(64,0);ctx.rotate(Math.PI/2);}
    if(side===2){ctx.translate(64,64);ctx.rotate(Math.PI);}
    if(side===3){ctx.translate(0,64);ctx.rotate(-Math.PI/2);}
    const depth=side===0?24:side===3?15:10;
    const grad=ctx.createLinearGradient(0,0,0,depth);grad.addColorStop(0,'rgba(23,20,16,.82)');grad.addColorStop(.22,'rgba(23,20,16,.45)');grad.addColorStop(1,'rgba(23,20,16,0)');
    ctx.fillStyle=grad;ctx.fillRect(0,0,64,depth);
    ctx.restore();
  }
}
function floorFixtureIndex(world,x,y) {
  const clear=(cx,cy)=>world.inside(cx,cy)&&!world.blocked(cx,cy);
  if(!clear(x,y))return -1;
  const pipe=(cx,cy)=>world.inside(cx,cy)&&initialRubble(cx,cy-1)&&((cx+cy*3)%12)<4;
  if(pipe(x,y))return 272+(pipe(x-1,y)?1:0)+(pipe(x+1,y)?2:0);
  const seed=(x*197+y*83+x*y*17)%997;
  if(seed%61===0)return 276;
  if(seed%73===0)return 277;
  if(seed%11===0&&initialRubble(x-1,y))return 278;
  if(seed%11===0&&initialRubble(x+1,y))return 279;
  return -1;
}
function spriteSource(scene,key) {
  const texture=scene.textures.get(key),bounds=FLOOR_PROP_FRAMES[key];
  if(!texture.has('trimmed'))texture.add('trimmed',0,bounds.x,bounds.y,bounds.w,bounds.h);
  const frame=texture.get('trimmed');
  return {image:texture.getSourceImage(),x:frame.cutX,y:frame.cutY,w:frame.cutWidth,h:frame.cutHeight};
}
function drawSprite(ctx,sprite,x,y,w,h,flip=false) {
  ctx.save();if(flip){ctx.translate(x+w,y);ctx.scale(-1,1);x=0;y=0;}
  ctx.drawImage(sprite.image,sprite.x,sprite.y,sprite.w,sprite.h,x,y,w,h);ctx.restore();
}
function floorFixture(ctx,type,sprites) {
  if(type<4) {
    const left=type&1?0:9,right=type&2?64:55;
    drawSprite(ctx,sprites.pipe,left,7,right-left,15);
    if(!(type&1))drawSprite(ctx,sprites.cap,left-5,6,10,17,true);
    if(!(type&2))drawSprite(ctx,sprites.cap,right-5,6,10,17);
  } else if(type===4) {
    drawSprite(ctx,sprites.drain,17,17,30,30);
  } else if(type===5) {
    drawSprite(ctx,sprites.vent,12,18,40,28);
  } else {
    drawSprite(ctx,sprites.cable,type===6?4:46,3,14,58);
  }
}
function drawMaterialSurface(ctx,source,material,variant) {
  const r=materialFrameRect(material,variant,source.width,source.height);
  // Rotate and mirror painted variants without changing the frame's scale or coverage.
  ctx.save();ctx.translate(32,32);ctx.rotate((variant%4)*Math.PI/2);
  ctx.scale(variant&4?-1:1,variant&8?-1:1);
  ctx.drawImage(source,r.x,r.y,r.w,r.h,-32,-32,64,64);ctx.restore();
}
function makeTerrainAtlas(scene,material='earth') {
  const key=material==='earth'?'terrain-atlas':'terrain-'+material;
  if(scene.textures.exists(key))return key;
  const variants=material==='earth'?16:materialDefinition(material).frames.length>1?8:4;
  const cornerBase=material==='earth'?288:variants*16;
  const texture=scene.textures.createCanvas(key,1088,Math.ceil((cornerBase+variants*8)/16)*68);
  const sprites=Object.fromEntries(['pipe','cap','vent','drain','cable'].map(name=>[name,spriteSource(scene,'prop-'+name)]));
  const ctx=texture.getContext(),source=scene.textures.get('material-surfaces').getSourceImage();
  const faceTexture=scene.textures.createCanvas('material-face-'+material,256,64),faceCtx=faceTexture.getContext();
  for(let i=0;i<4;i++){faceCtx.save();faceCtx.translate(i*64,0);drawMaterialSurface(faceCtx,source,material,i);faceCtx.fillStyle='rgba(13,18,20,.25)';faceCtx.fillRect(0,0,64,64);faceCtx.restore();}
  faceTexture.refresh();const face=faceTexture.getSourceImage();
  for(let variant=0;variant<variants;variant++)for(let mask=0;mask<16;mask++) {
    const index=variant*16+mask,ox=index%16*68+2,oy=Math.floor(index/16)*68+2;
    ctx.save();ctx.translate(ox,oy);ctx.beginPath();ctx.rect(0,0,64,64);ctx.clip();
    drawMaterialSurface(ctx,source,material,variant);
    for(let side=0;side<4;side++)if(mask&(1<<side))cutEdge(ctx,side,variant,face,mask);
    ctx.restore();
    // Extruded texels prevent neighbouring atlas variants bleeding into cell seams.
    const canvas=texture.getSourceImage();
    ctx.drawImage(canvas,ox,oy,64,1,ox,oy-2,64,2);
    ctx.drawImage(canvas,ox,oy+63,64,1,ox,oy+64,64,2);
    ctx.drawImage(canvas,ox,oy-2,1,68,ox-2,oy-2,2,68);
    ctx.drawImage(canvas,ox+63,oy-2,1,68,ox+64,oy-2,2,68);
  }
  if(material==='earth')for(let mask=0;mask<16;mask++){ctx.save();ctx.translate(mask*68+2,1090);floorShadow(ctx,mask);ctx.restore();}
  if(material==='earth')for(let type=0;type<8;type++){ctx.save();ctx.translate(type*68+2,1158);floorFixture(ctx,type,sprites);ctx.restore();}
  for(let variant=0;variant<variants;variant++)for(let type=0;type<8;type++) {
    const index=cornerBase+variant*8+type;
    ctx.save();ctx.translate(index%16*68+2,Math.floor(index/16)*68+2);
    ctx.beginPath();ctx.rect(0,0,64,64);ctx.clip();cornerPatch(ctx,type,variant,face);ctx.restore();
  }
  texture.refresh();return key;
}
class WorldTerrain {
  constructor(scene,world) {
    this.world=world;this.scene=scene;
    this.map=scene.make.tilemap({tileWidth:CELL,tileHeight:CELL,width:BASE_SIZE,height:BASE_SIZE});
    this.materialLayers=new Map();const earth=this.layersFor('earth');this.layer=earth.layer;this.corners=earth.corners;
    this.fixtures=this.map.createBlankLayer('bunker-fixtures',earth.tiles).setDepth(2);
    for(let y=0;y<BASE_SIZE;y++)for(let x=0;x<BASE_SIZE;x++)this.paintCell(x,y);
    scene.events.once('shutdown',()=>this.map.destroy());
  }
  layersFor(id) {
    const material=materialDefinition(id).id;if(this.materialLayers.has(material))return this.materialLayers.get(material);
    // Only materials present on this floor allocate a GPU atlas and tile layers.
    const key=makeTerrainAtlas(this.scene,material),tiles=this.map.addTilesetImage(key,key,CELL,CELL,2,4);
    const layer=this.map.createBlankLayer('surface-'+material,tiles).setDepth(3);
    const corners=Array.from({length:4},(_,i)=>this.map.createBlankLayer('corner-'+material+'-'+i,tiles).setDepth(3.1));
    const variants=material==='earth'?16:materialDefinition(material).frames.length>1?8:4;
    const group={tiles,layer,corners,variants,cornerBase:material==='earth'?288:variants*16};this.materialLayers.set(material,group);return group;
  }
  paintCell(x,y) {
    if(x<0||y<0||x>=BASE_SIZE||y>=BASE_SIZE)return;
    const group=this.layersFor(terrainMaterial(this.world,x,y));
    for(const other of this.materialLayers.values())if(other!==group){other.layer.removeTileAt(x,y);for(const corner of other.corners)corner.removeTileAt(x,y);}
    const rawIndex=terrainTileIndex(this.world,x,y),variant=((y%4)*4+x%4)%group.variants;
    const tile=group.layer.putTileAt(this.world.blocked(x,y)?variant*16+(rawIndex%16):rawIndex,x,y);
    terrainCornerTypes(this.world,x,y).forEach((type,i)=>{
      if(type<0)group.corners[i].removeTileAt(x,y);
      else group.corners[i].putTileAt(group.cornerBase+variant*8+type,x,y);
    });
    const fixture=floorFixtureIndex(this.world,x,y);
    if(fixture<0)this.fixtures.removeTileAt(x,y);else this.fixtures.putTileAt(fixture,x,y);
    // Distinct material artwork stays intact while existing drill damage remains visible.
    tile.tint=this.world.damage.has(y*BASE_SIZE+x)?0xf4d6aa:0xffffff;
    for(const layer of group.corners){const corner=layer.getTileAt(x,y);if(corner)corner.tint=tile.tint;}
  }
  refreshAround(x,y) {
    for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++)if(Math.abs(dx)+Math.abs(dy)<=2)this.paintCell(x+dx,y+dy);
  }
}

function bunkerFloorTexture(scene) {
  const key='bunker-floor-joined';
  if(scene.textures.exists(key))return key;
  const source=scene.textures.get('bunker-floor').getSourceImage();
  const texture=scene.textures.createCanvas(key,512,512),ctx=texture.getContext();
  // Mirrored neighbors share the same boundary pixels, including the slab joints.
  for(let y=0;y<2;y++)for(let x=0;x<2;x++) {
    ctx.save();ctx.translate(x?512:0,y?512:0);ctx.scale(x?-1:1,y?-1:1);
    ctx.drawImage(source,0,0,256,256);ctx.restore();
  }
  texture.refresh();return key;
}







const LIFT = {x:33,y:21};
const LIFT_BLOCKS = [{x:32,y:24},{x:33,y:24},{x:34,y:24}];
const FLOOR_LIFT = {x:25,y:7};
function liftBlockCount(world) { return LIFT_BLOCKS.filter(p=>world.blocked(p.x,p.y)).length; }
function liftFrameCell(x,y,center=LIFT) {
  const dx=x-center.x,dy=y-center.y;
  return Math.abs(dx)<=3&&dy>=-3&&dy<=3&&!(Math.abs(dx)<=1&&dy>=-1);
}
// Match the cropped sprite in LiftView instead of blocking a seven-cell square.
function liftGeometry(center=LIFT) {
  const scale=384/1077,x=(center.x+.5)*CELL-192,y=(center.y+.5)*CELL-1063*scale/2;
  const rect=(sx,sy,w,h)=>({x:x+(sx-127)*scale,y:y+(sy-40)*scale,width:w*scale,height:h*scale});
  return {deck:rect(333,320,665,565),colliders:[
    rect(127,40,1077,280),rect(127,320,206,565),rect(998,320,206,565),
    rect(127,885,291,160),rect(915,885,289,160)
  ]};
}
function ownedKeycards(progress) {
  const base=progress.base||progress;
  return [...new Set([...(Array.isArray(progress.keycards)?progress.keycards:[]),
    ...(base.rescued?[1]:[]),...(progress.armoryQuest?.briefed?[2]:[]),...(progress.repairQuest?.briefed?[3]:[]),...(progress.constructionQuest?.briefed?[4]:[])
  ].filter(n=>Number.isInteger(n)&&n>=1&&n<=100))].sort((a,b)=>a-b);
}
function liftDestinations(progress) {
  const highest=Math.min(100,Math.max(0,Math.floor(progress.highestFloor||0))),cards=new Set(ownedKeycards(progress));
  const last=Math.min(100,Math.max(highest+1,...cards));
  return [{floor:0,enabled:true},...Array.from({length:last},(_,i)=>({floor:i+1,enabled:i+1<=highest||cards.has(i+1)}))];
}
// The radio shows only the current mission's unused access card. Owned cards stay saved.
function questKeycard(progress) {
 const base=progress.base||progress,armory=progress.armoryQuest||{},repair=progress.repairQuest||{};
 const target=progress.constructionQuest?.briefed?(progress.constructionQuest.rescued?null:4):repair.briefed?(repair.ready?null:3):armory.briefed?(armory.ready?null:2):base.rescued?1:null;
 if(target==null||target<=(progress.highestFloor||0)||target===(progress.floor||0))return null;
 return ownedKeycards(progress).includes(target)?target:null;
}

// Separate mine state: the lift never swaps the base's excavated cells with a floor.
class FloorWorld {
  constructor(progress={},floor=1) {
    this.floor=[1,2,3,4].includes(floor)?floor:1;this.x=Number.isInteger(progress.x)?progress.x:FLOOR_LIFT.x;
    this.y=Number.isInteger(progress.y)?progress.y:FLOOR_LIFT.y;
    this.cleared=new Set(Array.isArray(progress.cleared)?progress.cleared.filter(n=>Number.isInteger(n)&&n>=0&&n<BASE_SIZE*BASE_SIZE):[]);
    this.damage=new Map(Array.isArray(progress.damage)?progress.damage.filter(v=>Array.isArray(v)&&Number.isInteger(v[0])&&v[0]>=0&&v[0]<BASE_SIZE*BASE_SIZE&&Number.isFinite(v[1])&&v[1]>0&&v[1]<1):[]);
    this.materialSeed=validMaterialSeed(progress.materialSeed)?progress.materialSeed:createMaterialSeed();
    this.materialOverrides=restoreMaterialOverrides(progress.materialOverrides);
    // Keep the material of partially drilled old blocks during migration.
    if(!validMaterialSeed(progress.materialSeed))for(const key of this.damage.keys()) {
      const x=key%BASE_SIZE,y=Math.floor(key/BASE_SIZE);
      this.materialOverrides.set(key,this.floor===2&&((x*31+y*17+x*y)%100)<38?'stone':'earth');
    }
    if(validMaterialSeed(progress.materialSeed)&&progress.materialGeneration!==2)for(const key of this.damage.keys()) {
      if(!this.materialOverrides.has(key))this.materialOverrides.set(key,legacyDepositMaterial(this.materialSeed,this.floor,key%BASE_SIZE,Math.floor(key/BASE_SIZE)));
    }
    this.hiddenArtifacts=restoreHiddenArtifacts(progress.hiddenArtifacts,this);this.rescued=true;this.heard=true;
    const parked=progress.drive;
    const hasParked=parked&&Number.isFinite(parked.x)&&Number.isFinite(parked.y)&&Math.floor(parked.x/CELL)===this.x&&Math.floor(parked.y/CELL)===this.y;
    const px=hasParked?parked.x:(this.x+.5)*CELL,py=hasParked?parked.y:(this.y+.5)*CELL;
    if(!this.inside(this.x,this.y)||this.blocked(this.x,this.y)||liftGeometry(FLOOR_LIFT).colliders.some(rect=>circleHitsRect(px,py,rect))){this.x=25;this.y=7;}
  }
  inside(x,y){return x>=2&&y>=2&&x<48&&y<48;}
  blocked(x,y){const item=this.floor===4?((x>=34&&x<=36&&y>=29&&y<=32)||BUILDER_GUARDS.some(p=>x===p.x&&y===p.y)):this.floor===3?((x===18&&y===34)||(x===36&&y===39)||[{x:25,y:12},{x:13,y:24},{x:38,y:24},{x:19,y:33},{x:35,y:38}].some(p=>Math.abs(x-p.x)<=1&&Math.abs(y-p.y)<=1)):this.floor===2?((x===17&&y===27)||(x===36&&y===35)):((x===18&&y===20)||(x===32&&y===29));return this.inside(x,y)&&!item&&!(x>=22&&x<=28&&y>=4&&y<=11)&&!this.cleared.has(y*BASE_SIZE+x);}
  material(x,y){return this.materialOverrides.get(y*BASE_SIZE+x)||depositMaterial(this.materialSeed,this.floor,x,y);}
  hardness(x,y){return this.material(x,y)==='earth'?1:2.5;}
  drill(x,y,amount){if(!this.blocked(x,y))return false;const key=y*BASE_SIZE+x,next=(this.damage.get(key)||0)+amount/this.hardness(x,y);if(next>=1){this.cleared.add(key);this.damage.delete(key);return true;}this.damage.set(key,next);return false;}
  canRescue(){return false;}
  snapshot(){return {hiddenArtifacts:{created:this.hiddenArtifacts.created,items:this.hiddenArtifacts.items.map(i=>({...i}))},location:'floor',floor:this.floor,materialSeed:this.materialSeed,materialGeneration:2,materialOverrides:[...this.materialOverrides],x:this.x,y:this.y,cleared:[...this.cleared],damage:[...this.damage]};}
}





class LiftView {
  constructor(scene,center) {
    this.scene=scene;this.x=(center.x+.5)*CELL;this.y=(center.y+.5)*CELL;
    const texture=scene.textures.get('freight-lift'),scale=384/1077;
    const originX=this.x-1077*scale/2,originY=this.y-1063*scale/2;
    const pieces={top:[127,40,1077,280],bottomLeft:[127,885,291,218],bottomRight:[915,885,289,218],ramp:[418,885,497,218],left:[127,320,206,565],right:[998,320,206,565],deck:[333,320,665,565],gate:[334,280,664,32]};
    const image=(key,depth)=>{const [x,y,w,h]=pieces[key];if(!texture.has(key))texture.add(key,0,x,y,w,h);return scene.add.image(originX+(x-127)*scale,originY+(y-40)*scale,'freight-lift',key).setOrigin(0).setScale(scale).setDepth(depth);};
    this.deckX=originX+(333-127)*scale;this.deckY=originY+(320-40)*scale;
    this.deckW=665*scale;this.deckH=565*scale;
    this.colliders=liftGeometry(center).colliders;
    this.shaft=scene.add.rectangle(this.deckX,this.deckY,this.deckW,this.deckH,0x0c1719).setOrigin(0).setDepth(2);
    this.platform=image('deck',2.2);
    // The entry ramp is driveable floor; only the housing covers the drill.
    this.ramp=image('ramp',2.2);this.parts=['top','bottomLeft','bottomRight','left','right'].map(key=>image(key,25));
    if(!texture.has('gate'))texture.add('gate',0,...pieces.gate);
    this.gates=[-1,1].map(side=>scene.add.image(this.x+side*this.deckW,this.deckY+this.deckH-7,'freight-lift','gate').setDisplaySize(this.deckW/2,12).setDepth(26));
    const gateClip=scene.make.graphics({x:0,y:0,add:false});gateClip.fillRect(this.deckX,this.deckY+this.deckH-15,this.deckW,24);this.gateMask=gateClip.createGeometryMask();this.gates.forEach(g=>g.setMask(this.gateMask));
    const shaftClip=scene.make.graphics({x:0,y:0,add:false});shaftClip.fillRect(this.deckX,this.deckY,this.deckW,this.deckH+2);this.mask=shaftClip.createGeometryMask();
    // Actual amber lamps in the four painted corner housings.
    this.lamps=[[200,140],[1135,140],[200,928],[1135,928]].map(([x,y])=>({x:originX+(x-127)*scale,y:originY+(y-40)*scale}));
    this.elapsed=0;this.ambient=scene.add.graphics().setDepth(26);
    this.indicator=scene.add.circle(this.x+169,this.y+24,4,0x86f672).setDepth(27);
    scene.events.once('shutdown',()=>{this.mask.destroy();this.gateMask.destroy();shaftClip.destroy();gateClip.destroy();});
  }
  contains(rig){return rig.x>this.deckX+21&&rig.x<this.deckX+this.deckW-21&&rig.y>this.deckY+21&&rig.y<this.deckY+this.deckH-21;}
  powered(value){this.ready=value;this.indicator.setFillStyle(value?0x74ee87:0xffad46);this.parts.forEach(p=>p.setDepth(value?25:2.5));}
  update(delta) {
    this.elapsed+=delta;const pulse=.45+.5*(.5+.5*Math.sin(this.elapsed*.0017));this.indicator.setAlpha(this.ready?pulse:1);
    const g=this.ambient;g.clear();g.setDepth(27);
    for(let i=0;i<this.lamps.length;i++) {
      const p=this.lamps[i];
      if(!this.ready){g.fillStyle(0x26312e,.65);g.fillEllipse(p.x,p.y,14,22);continue;}
      // Diagonal pairs breathe alternately, with a bright core and soft amber halo.
      const light=.16+.7*(.5+.5*Math.sin(this.elapsed*.0022+(i===0||i===3?0:Math.PI)));
      g.fillStyle(0x493624,(1-light)*.65);g.fillEllipse(p.x,p.y,13,21);
      g.fillStyle(0xffb43e,light*.18);g.fillCircle(p.x,p.y,18);
      g.fillStyle(0xffc257,light*.65);g.fillEllipse(p.x,p.y,13,21);
      g.fillStyle(0xffedaf,light);g.fillEllipse(p.x,p.y,5,13);
    }
    if(!this.ready)return;
    g.fillStyle(0xffce75,.055+.025*Math.sin(this.elapsed*.0017));g.fillEllipse(this.x,this.deckY+this.deckH-5,this.deckW*.8,22);
  }
  motor(duration=.8) {
    if(!readSettings().sound)return;
    try {
      const audio=new (window.AudioContext||window.webkitAudioContext)(),osc=audio.createOscillator(),gain=audio.createGain(),filter=audio.createBiquadFilter();
      audio.resume().catch(()=>{});osc.type='sawtooth';osc.frequency.setValueAtTime(65,audio.currentTime);osc.frequency.linearRampToValueAtTime(90,audio.currentTime+duration*.6);
      filter.type='lowpass';filter.frequency.value=180;gain.gain.setValueAtTime(.001,audio.currentTime);gain.gain.linearRampToValueAtTime(.025,audio.currentTime+.08);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);
      osc.connect(filter);filter.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+duration);osc.onended=()=>audio.close().catch(()=>{});
    } catch { /* Mechanical sound is optional when browser audio is unavailable. */ }
  }
  tween(config){return new Promise(resolve=>this.scene.tweens.add({...config,onComplete:resolve}));}
  async depart(rig,shadow,targetFloor) {
    const s=this.scene;this.motor(1.1);s.cameras.main.stopFollow();s.cameras.main.shake(180,.001);rig.setPosition(this.x,this.deckY+this.deckH/2);shadow.setVisible(false);
    await Promise.all(this.gates.map((gate,i)=>this.tween({targets:gate,x:this.x+(i===0?-1:1)*this.deckW/4,duration:330,ease:'Cubic.Out'})));
    rig.setMask(this.mask);this.platform.setMask(this.mask);this.indicator.setFillStyle(0xffcb55);
    const dy=targetFloor===0?-55:55;
    await Promise.all([this.tween({targets:rig,y:rig.y+dy,alpha:.1,scale:.92,duration:850,ease:'Sine.In'}),this.tween({targets:this.platform,y:this.platform.y+dy,alpha:.15,duration:850,ease:'Sine.In'})]);
    await new Promise(resolve=>{s.cameras.main.once('camerafadeoutcomplete',resolve);s.cameras.main.fadeOut(230,8,19,21);});
  }
  async arrive(rig,shadow) {
    this.scene.cameras.main.stopFollow();this.scene.cameras.main.centerOn(this.x,this.deckY+this.deckH/2);
    rig.setPosition(this.x,this.deckY+this.deckH/2+45).setAlpha(.15).setScale(.92).setMask(this.mask);shadow.setVisible(false);
    const y=this.platform.y;this.platform.setY(y+45).setAlpha(.15).setMask(this.mask);
    this.gates.forEach((g,i)=>g.x=this.x+(i===0?-1:1)*this.deckW/4);
    await Promise.all([this.tween({targets:rig,y:this.deckY+this.deckH/2,alpha:1,scale:1,duration:650,ease:'Sine.Out'}),this.tween({targets:this.platform,y,alpha:1,duration:650,ease:'Sine.Out'})]);
    await Promise.all(this.gates.map((gate,i)=>this.tween({targets:gate,x:this.x+(i===0?-1:1)*this.deckW,duration:330,ease:'Cubic.Out'})));
    rig.clearMask();this.platform.clearMask();shadow.setVisible(true);this.powered(true);this.scene.cameras.main.startFollow(rig,true,.10,.10);
  }
}


